  "pricing.docTitle": "Precios del Trip Pass",
  "pricing.compareTitle": "Lo que sigue gratis y lo que añade un pase",
  "pricing.passCol": "Un Trip Pass añade",
  "pricing.free1": "Cada lugar, con su precio y su mapa",
  "pricing.free2": "El planificador de viajes y el de días",
  "pricing.free3": "Un viaje guardado",
  "pricing.free4": "{n} planes del bot de Carta",
  "pricing.free5": "Enlaces para compartir y planear con amigos",
  "pricing.free6": "Archivos GPX de senderos y rutas",
  "pricing.plansTitle": "Dos formas de pagar",
  "pricing.qTitle": "Antes de pagar",
  "pricing.afterQ": "¿Qué pasa después de {days} días?",
  "pricing.afterA": "El Trip Pass se acaba. Nada se renueva y no se cobra nada más. Tus viajes siguen guardados y planificar sigue siendo gratis. Las exportaciones y los planes extra esperan a un nuevo pase.",
  "pricing.restoreQ": "Pagué en otro dispositivo. ¿Dónde está mi pase?",
  "pricing.restoreA": "Tu pase es de tu cuenta, no del dispositivo. Inicia sesión con la cuenta con la que pagaste y ahí está. ¿Sigue sin aparecer? Escribe a {email}.",
  "pricing.restoreGo": "Comprobar mi pase de nuevo",
  "pricing.restoreSignIn": "Iniciar sesión",
  "pricing.restoreDone": "Comprobado. Tu plan: {name}.",
  "pass.continueAddDays": "Añadir {n} días, {price}",
  "pass.carryOver": "Los días que te quedan del Trip Pass se mantienen.",
  "pass.current1": "Te queda 1 día de {name}.",
  "pass.cancellingNote": "Tu plan anual termina el {date}. Mantenlo y se renueva como antes.",
  "pass.resume": "Mantener mi plan anual",
  "account.fqgPlanning": "Planificar",
  "account.fqgPrices": "Precios",
  "account.fqgPasses": "Pases y pago",
  "account.fqgAccount": "Cuenta y datos",
  "account.fq.planQ": "¿Cómo planeo un viaje?",
  "account.fq.planA": "Abre el planificador de viajes, elige fechas y lugares, y Carta ordena las paradas y pone precio a cada cama, cada día y cada trayecto. El planificador de días llena luego cada día hora a hora.",
  "account.fq.togetherQ": "¿Puedo planear un viaje con amigos?",
  "account.fq.togetherA": "Sí. En Mis viajes, elige Invitar en un viaje: quien tenga el enlace puede iniciar sesión y editar la ruta contigo. Un enlace solo para ver funciona sin cuenta.",
  "account.fq.bookQ": "¿Puedo reservar con Carta?",
  "account.fq.bookA": "No. Carta pone precio y planea el viaje, y luego te envía a la aerolínea, al tren o al anfitrión para reservar directamente con ellos.",
  "account.fq.missingQ": "Mi pueblo no aparece. ¿Y ahora?",
  "account.fq.missingA": "El planificador de días funciona igual: escribe el pueblo y lo busca en directo. El catálogo crece con cada actualización.",
  "account.fq.differentQ": "¿En qué se diferencia Carta de Google Maps o Wanderlog?",
  "account.fq.differentA": "Google Maps te lleva hasta allí y Wanderlog guarda el plan que tú escribiste, pero ninguno sabe lo que cuesta una cama o un día. Carta planifica todo el viaje en un solo lugar, con lo que cuesta cada día: una cama más comida y bebida, con precio para cada lugar. Carta nunca navega, así que cada día y cada trayecto se abre en Google Maps.",
  "account.fq.dayQ": "¿Qué incluye el precio por día?",
  "account.fq.dayA": "Una persona, un día: una cama para la noche más comida y bebida (una comida sentado, una comida rápida, bebidas), según tu Lifestyle. No incluye: el viaje hasta allí, el transporte local y las entradas.",
  "account.fq.estQ": "¿Por qué un precio lleva est.?",
  "account.fq.estA": "Es una estimación: no se midieron los precios del pueblo, así que Carta usa el nivel del país. Un precio medido no lleva marca.",
  "account.fq.lifestyleQ": "¿Por qué cambiaron los precios al cambiar el Lifestyle?",
  "account.fq.lifestyleA": "Porque son tus precios. Una cama en dormitorio y un alojamiento entero con cena fuera son viajes distintos, y un solo ajuste mueve cada cifra de la app.",
  "account.fq.flightsQ": "¿Carta muestra precios de vuelos?",
  "account.fq.flightsA": "Sí. Carta muestra el vuelo más barato de Google Flights para tus días, con la aerolínea, los horarios y cuándo se comprobó, más la tarifa habitual de equipaje como estimación. Un billete que añadas lo sustituye.",
  "account.fq.addsQ": "¿Qué añade un pase?",
  "account.fq.addsA": "Gratis conserva {freePlans} planes del bot de Carta y un viaje guardado. Un Trip Pass añade exportar a PDF, calendario y mapa, todos tus viajes guardados, leer reservas, más planes de día del bot de Carta y búsquedas en directo de eventos y horarios. Compartir un viaje y planear con amigos siguen siendo gratis.",
  "account.fq.differenceQ": "¿Qué diferencia hay entre el Trip Pass y el plan anual?",
  "account.fq.differenceA": "El Trip Pass cuesta {tripPrice} una vez y dura {tripDays} días, sin renovación. El plan anual cuesta {yearPrice} al año y se renueva hasta que lo canceles.",
  "account.fq.cancelQ": "¿Cómo cancelo el plan anual?",
  "account.fq.cancelA": "En Cuenta, en Tu plan, elige Cancelar plan anual. Dura hasta el final del año pagado y no se cobra nada más.",
  "account.fq.refundQ": "¿Puedo obtener un reembolso?",
  "account.fq.refundA": "Sí, en los 14 días siguientes al pago si no usaste el pase o el plan. Escribe a {email} desde la dirección de tu cuenta.",
  "account.fq.needQ": "¿Necesito una cuenta?",
  "account.fq.needA": "No para explorar o planear. Una cuenta guarda tus viajes en todos tus dispositivos, abre el bot de Carta y te deja planear con amigos.",
  "account.fq.whereQ": "¿Dónde se guardan mis viajes?",
  "account.fq.whereA": "En tu cuenta cuando inicias sesión, así que se abren en cualquier dispositivo. Sin sesión, se quedan en este navegador.",
  "account.fq.deleteQ": "¿Cómo borro mi cuenta y mis datos?",
  "account.fq.deleteA": "En Cuenta, abre Tus datos y elige Eliminar mi cuenta. Todo se borra al momento de los servidores de Carta; antes puedes descargar una copia.",
  "account.faqSearch": "Buscar en las preguntas",
  "account.faqSearchPh": "Buscar, por ejemplo reembolso",
